-- ============================================================
-- DW ORGANIZACIONAL - DADOS EXTERNOS
-- 500 registros sintéticos
-- id_dado_externo = chave natural/de origem para rastreabilidade
-- ============================================================

CREATE TABLE IF NOT EXISTS fontes_externas.dados_externos (
    id_dado_externo    VARCHAR(100) PRIMARY KEY,
    data_referencia    DATE NOT NULL,
    tipo_dado          VARCHAR(50) NOT NULL,
    indicador          VARCHAR(100) NOT NULL,
    descricao          VARCHAR(200),
    valor              NUMERIC(18,6) NOT NULL,
    unidade            VARCHAR(50),
    fonte              VARCHAR(100) NOT NULL,
    referencia_origem  VARCHAR(200),
    data_carga         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE dados_externos IS
'Dados externos sintéticos utilizados pelo DW Organizacional.';

COMMENT ON COLUMN dados_externos.id_dado_externo IS
'Chave natural/de origem preservada para rastreabilidade, metadados e auditoria.';

COMMENT ON COLUMN dados_externos.data_referencia IS
'Data ou período ao qual o indicador externo se refere.';

COMMENT ON COLUMN dados_externos.fonte IS
'Origem do dado. Neste exercício, os registros são sintéticos.';

